import {gasCases,gasSource} from './gas-routes-content.mjs';
import {newGasWork,changeGasWork,gasGuidesView,lastGasGuide,keepGasGuide,gasLegGeometry} from './gas-routes-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>structuredClone(x),button=(attrs,text,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
let visit=null;
export function resetGasRoutes(){visit=null;}
function makeSlot(source,work){return {source:clone(source),work:clone(work||newGasWork(source)),turn:'follow',leg:source.legs[0].id,folds:{},status:''};}
function state(book,owner){if(!visit||visit.book!==book||visit.owner!==owner){visit={book,owner,screen:'draft',active:'oxygen',card:null,drafts:new Map(),copies:new Map(),readonly:new Map(),page:null};visit.drafts.set('oxygen',makeSlot(gasSource('oxygen')));}return visit;}
const slot=v=>v.screen==='draft'?v.drafts.get(v.active):v.screen==='card'?v.readonly.get(v.card):null;
const method=(s,id)=>s.methods.find(m=>m.id===id),node=(s,id)=>s.nodes.find(n=>n.id===id);
const linkName=(s,l,i=s.legs.indexOf(l))=>`Link ${i+1}: ${node(s,l.from).label} → ${node(s,l.to).label}`;
function glyph(n,r){const fill=n.art==='blood'?'#8e303c':n.art==='sac'?'#c6d7c5':n.art==='cell'?'#e6d9a9':'#dbe9ed';let art;if(n.art==='blood')art=`<ellipse rx="${r}" ry="${r*.78}" fill="${fill}"/><ellipse rx="${r*.72}" ry="${r*.48}" fill="none" stroke="#b65d68" stroke-width="${r*.1}"/>`;else if(n.art==='sac')art=`<path d="M${-r*.7} ${-r*.6} Q0 ${-r*1.25} ${r*.7} ${-r*.6} Q${r*1.4} ${r*.6} 0 ${r} Q${-r*1.4} ${r*.6} ${-r*.7} ${-r*.6}Z" fill="${fill}" stroke="#397958" stroke-width="${r*.08}"/>`;else if(n.art==='cell')art=`<ellipse rx="${r}" ry="${r*.87}" fill="${fill}" stroke="#a57a34" stroke-width="${r*.08}"/><circle cx="${r*.58}" cy="${r*.36}" r="${r*.18}" fill="#a57a34"/>`;else art=`<path d="M${-r} 0 Q${-r*.8} ${-r*.6} ${-r*.35} ${-r*.45} Q0 ${-r*1.2} ${r*.45} ${-r*.5} Q${r*1.3} ${-r*.35} ${r*.8} ${r*.5} H${-r*.7} Q${-r*1.2} ${r*.35} ${-r} 0Z" fill="${fill}" stroke="#3d6b7a" stroke-width="${r*.08}"/>`;return art;}
function diagram(s,w,activeLeg=null){const r=s.world.width*.045,selected=node(s,w.at),color=s.gas.symbol==='circle'?'#3d6b7a':'#a57a34',badge=s.gas.symbol==='circle'?`<circle r="${r*.22}"/>`:`<path d="M0 ${-r*.22} L${r*.22} 0 0 ${r*.22} ${-r*.22} 0Z"/>`;return `<svg class="gas-diagram" role="img" aria-label="${esc(`${s.gas.label} route. ${activeLeg?`Highlighted ${linkName(s,s.legs.find(l=>l.id===activeLeg))}.`:`Selected stop ${s.nodes.indexOf(selected)+1}: ${selected.label}.`} Numbers follow this route's itinerary.`)}" viewBox="0 0 ${s.world.width} ${s.world.height}"><g fill="#397958" stroke="#397958">${s.legs.map(l=>{const g=gasLegGeometry(s,l.id);return `<g data-gas-arrow="${esc(l.id)}" data-gas-selected-link="${l.id===activeLeg}"><line x1="${g.start.x}" y1="${g.start.y}" x2="${g.end.x}" y2="${g.end.y}" stroke="${l.id===activeLeg?color:'#397958'}" stroke-width="${g.strokeWidth*(l.id===activeLeg?2.2:1)}"/><polygon fill="${l.id===activeLeg?color:'#397958'}" stroke="none" points="${g.head.map(p=>`${p.x},${p.y}`).join(' ')}"/></g>`;}).join('')}</g>${s.nodes.map((n,i)=>`<g data-gas-icon="${esc(n.id)}" transform="translate(${n.x} ${n.y})">${!activeLeg&&n.id===w.at?`<circle r="${r*1.12}" fill="none" stroke="${color}" stroke-width="${r*.07}"/>`:''}${glyph(n,r)}<circle class="gas-number-patch" r="${r*.65}" fill="white"/><text text-anchor="middle" dominant-baseline="central" style="font-size:${s.world.width/16}px" fill="#183f39">${i+1}</text>${!activeLeg&&n.id===w.at?`<g data-gas-badge transform="translate(${r*.62} ${-r*.62})" fill="${color}">${badge}</g>`:''}</g>`).join('')}</svg>`;}
function legend(s,w){return `<ol class="gas-legend">${s.legs.map(l=>`<li><strong>${esc(linkName(s,l))}</strong><span>Your label: ${esc(method(s,w.guide.find(g=>g.legId===l.id)?.methodId)?.label||'Not labeled')}</span></li>`).join('')}</ol>`;}
function fold(a,key,title,body){return `<details data-gas-fold="${key}"${a.folds[key]?' open':''}><summary>${esc(title)}</summary>${body}</details>`;}
function activePage(a,readonly,copy){const s=a.source,w=a.work,current=node(s,w.at),at=s.nodes.indexOf(current),available=s.nodes.filter(n=>!readonly||w.seen.includes(n.id)),position=available.indexOf(current),leg=s.legs.find(l=>l.id===a.leg)||s.legs[0],chosen=w.guide.find(g=>g.legId===leg.id)?.methodId;return `<h2 id="gas-title" tabindex="-1">${esc(s.title)}</h2>${readonly?`<p>Kept guide · your record stays as you left it.</p>${button('data-gas-copy',copy?'Return to your copy':'Work on a copy',true)}`:button('data-gas-keep','Keep this guide',true)}<p id="gas-status" role="status" tabindex="-1">${esc(a.status)}</p><div class="gas-actions" aria-label="Two ways to explore">${button(`data-gas-turn="follow" aria-pressed="${a.turn==='follow'}"`,'Follow the gas',a.turn==='follow')}${button(`data-gas-turn="make" aria-pressed="${a.turn==='make'}"`,'Make a guide',a.turn==='make')}</div><p class="gas-context">${esc(s.context)}</p>${a.turn==='make'?`<p data-gas-highlight-text>Highlighted: ${esc(linkName(s,leg))}</p>`:''}${diagram(s,w,a.turn==='make'?leg.id:null)}<p class="gas-loop">${esc(s.loopNote)}</p><section class="gas-current">${a.turn==='follow'?`<p class="gas-kicker">${esc(s.gas.label)} · Stop ${at+1} of ${s.nodes.length}</p><h3 id="gas-current-title" tabindex="-1">${esc(current.label)}</h3><p>${esc(current.description)}</p><div class="gas-actions">${button(`data-gas-previous${position<=0?' disabled':''}`,'Previous stop')}${button(`data-gas-next${position>=available.length-1?' disabled':''}`,'Next stop')}</div><ol class="gas-stations">${s.nodes.map((n,i)=>`<li>${button(`data-gas-node="${esc(n.id)}" aria-pressed="${n.id===w.at}"${readonly&&!w.seen.includes(n.id)?' disabled':''}`,`${i+1}. ${n.label}`,n.id===w.at)}</li>`).join('')}</ol>${readonly?'<p>Only stops you visited are open here. Work on a copy to visit other stops.</p>':''}`:`<p class="gas-kicker">${esc(s.gas.label)} · Last Follow stop: ${esc(current.label)}</p><h3 id="gas-current-title" tabindex="-1">Choose words for a link</h3><label>Current link <select data-gas-leg>${s.legs.map(l=>`<option value="${esc(l.id)}"${l.id===leg.id?' selected':''}>${esc(linkName(s,l))}</option>`).join('')}</select></label><p>${esc(linkName(s,leg))}</p>${readonly?`<p data-gas-choice>Your label: ${esc(method(s,chosen)?.label||'Not labeled')}</p>`:`<div class="gas-methods">${s.methods.map(m=>button(`data-gas-method="${esc(m.id)}" aria-pressed="${chosen===m.id}"`,m.label+' — '+m.description,chosen===m.id)).join('')}</div>${button(`data-gas-remove${!chosen?' disabled':''}`,'Remove this label')}`}${legend(s,w)}${!readonly&&!w.referenceShown?button('data-gas-reference','Show route notes'):''}${w.referenceShown?`<section class="gas-reference"><h4>Route notes to compare with your labels</h4>${s.legs.map(l=>`<p><strong>${esc(linkName(s,l))}</strong><br><span data-gas-choice>Your label: ${esc(method(s,w.guide.find(g=>g.legId===l.id)?.methodId)?.label||'Not labeled')}</span><br>Route note: ${esc(method(s,l.methodId).label)}. ${esc(l.text)}</p>`).join('')}</section>`:''}`}</section>${fold(a,'about','About this route',`<p>${esc(s.notice)}</p>`)}${fold(a,'directions','Why these overall directions?',`<p>${esc(s.gradientNote)}</p>`)}${fold(a,'transport','What the badge leaves out?',`<p>${esc(s.transportNote)}</p>`)}${fold(a,'help','Optional help',`${s.teaching.slice(0,w.exampleSeen).map(t=>`<p>${esc(t)}</p>`).join('')}${readonly?'':button(`data-gas-example${w.exampleSeen>=s.teaching.length?' disabled':''}`,w.exampleSeen?'Next help frame':'Show a help frame')}`)}${readonly?`<p>${esc(s.returnQuestion)}</p>`:''}`;}
function shelf(v){const view=gasGuidesView(v.book),total=view.items.length;if(v.page===null){const last=view.items.findLast(x=>x.readable);v.page=Math.floor((last?.index??Math.max(0,total-1))/8);}v.page=Math.max(0,Math.min(v.page,Math.max(0,Math.ceil(total/8)-1)));const start=v.page*8;return `<h2 id="gas-title" tabindex="-1">Kept guides</h2>${view.status==='unavailable'?'<p>This saved format is unavailable here. Its original stays in your Notes download. Your visit drafts remain open.</p>':''}${total?`<p>Guides ${start+1}–${Math.min(start+8,total)} of ${total}</p><ol start="${start+1}">${view.items.slice(start,start+8).map(x=>`<li>${x.readable?button(`data-gas-card="${esc(x.id)}"`,`Guide ${x.index+1} · ${x.raw.source.title}`):'<p>Guide unavailable here. Its original stays unchanged in your Notes download.</p>'}</li>`).join('')}</ol><div class="gas-actions">${button(`data-gas-page="-1"${start===0?' disabled':''}`,'Previous guides')}${button(`data-gas-page="1"${start+8>=total?' disabled':''}`,'Next guides')}</div>`:view.status==='unavailable'?'':'<p>No guide has been kept yet.</p>'}`;}
export function gasRoutesPage(book,owner){const v=state(book,owner);if(v.screen==='card'){const item=gasGuidesView(book).items.find(x=>x.readable&&x.id===v.card);if(item){const old=v.readonly.get(item.id);if(!old||old.raw!==item.raw||old.rawSource!==item.raw.source||old.rawWork!==item.raw.work)v.readonly.set(item.id,Object.assign(makeSlot(item.raw.source,item.raw.work),{raw:item.raw,rawSource:item.raw.source,rawWork:item.raw.work}));}}const a=v.screen==='card'&&!gasGuidesView(book).items.some(x=>x.readable&&x.id===v.card)?null:slot(v);return `<div class="gas-page" data-cs-root data-gas-root><header><div class="gas-actions">${button('data-gas-back','Back to Cell Studio')}${button('data-gas-guide','Your guide')}${button('data-gas-shelf','Kept guides')}${button('data-gas-hear data-speak=""','Hear this page')}</div><h1>Air and blood</h1></header><div class="gas-actions" aria-label="Choose a gas">${gasCases.map(s=>button(`data-gas-case="${esc(s.id)}"`,`Follow ${s.gas.label}`,v.screen==='draft'&&v.active===s.id)).join('')}</div>${v.screen==='shelf'?shelf(v):a?activePage(a,v.screen==='card',v.copies.has(v.card)):'<h2 id="gas-title" tabindex="-1">This guide is unavailable here</h2><p>Your original stays in your Notes download.</p>'}<p class="gas-visit-note">Leaving this visit, reloading, changing explorer or importing Notes clears guides that have not been kept.</p></div>`;}
export function bindGasRoutes(book,ctx){
 const owner=()=>typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,v=state(book,owner()),screen=v.screen,active=v.active,card=v.card,a=slot(v),source=a?.source,root=document.querySelector('[data-gas-root]');if(!root)return;
 const back=root.querySelector('[data-gas-back]');if(back)back.textContent=ctx.backLabel||'Back to Cell Studio';
 const parent=root.parentNode,ancestry=[];for(let n=root;n&&n!==document;n=n.parentNode)ancestry.push([n,n.parentNode]);const lineage=new WeakMap(),raw=a?.raw,rawSource=a?.rawSource,rawWork=a?.rawWork;let expected=a?.work;
 const live=n=>visit===v&&owner()===v.owner&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook)===book&&ctx.isActive()&&ctx.isGasActive()&&location.hash==='#living/bodies'&&root.isConnected&&root.parentNode===parent&&document.querySelector('[data-gas-root]')===root&&n.isConnected&&root.contains(n)&&(!lineage.has(n)||lineage.get(n)===n.parentNode)&&ancestry.every(([child,p])=>child.parentNode===p)&&v.screen===screen&&v.active===active&&v.card===card&&slot(v)===a&&a?.source===source&&a?.work===expected&&(screen!=='card'||!raw||gasGuidesView(book).items.some(x=>x.readable&&x.id===card&&x.raw===raw&&x.raw.source===rawSource&&x.raw.work===rawWork));
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();},focus=selector=>{const n=document.querySelector(`[data-gas-root] ${selector}`);if(n)n.focus({preventScroll:true});else ctx.focus?.(selector);},redraw=(selector='#gas-title')=>{ctx.render();focus(selector);},editable=()=>screen==='draft'&&a;
 const guard=n=>{lineage.set(n,n.parentNode);for(const t of ['click','input','change','toggle','keydown','focusin'])n.addEventListener(t,e=>{if(!live(n)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});};guard(root);root.querySelectorAll('button,a,details,summary,select,[data-speak]').forEach(guard);
 function status(text){if(a)a.status=text;const n=root.querySelector('#gas-status');if(n){n.textContent=text;n.focus({preventScroll:true});}}
 function change(action,value){if(!editable())return false;const next=changeGasWork(source,a.work,action,value);if(!next)return false;a.work=next;expected=next;return true;}
 function on(selector,fn,target='#gas-title'){root.querySelectorAll(selector).forEach(n=>n.addEventListener('click',()=>{if(!live(n)||n.disabled)return;stop();if(fn(n)!==false)redraw(typeof target==='function'?target(n):target);}));}
 const attr=(name,value)=>`[data-gas-${name}="${CSS.escape(value)}"]`;
 on('[data-gas-back]',()=>{ctx.onBack();return false;});on('[data-gas-shelf]',()=>{v.screen='shelf';});
 on('[data-gas-guide]',()=>{if(!v.drafts.has(v.active)){v.active='oxygen';if(!v.drafts.has(v.active))v.drafts.set(v.active,makeSlot(gasSource(v.active)));}v.screen='draft';});
 on('[data-gas-case]',n=>{const id=n.dataset.gasCase;if(!v.drafts.has(id))v.drafts.set(id,makeSlot(gasSource(id)));v.active=id;v.screen='draft';});
 on('[data-gas-card]',n=>{v.card=n.dataset.gasCard;v.screen='card';});on('[data-gas-page]',n=>{v.page+=Number(n.dataset.gasPage);});
 on('[data-gas-turn]',n=>{if(!a)return false;a.turn=n.dataset.gasTurn;},'#gas-current-title');
 function station(id){if(!a||!node(source,id))return false;if(screen==='card'){if(!a.work.seen.includes(id))return false;a.work={...a.work,at:id};expected=a.work;return true;}return change('station',id);}
 on('[data-gas-node]',n=>station(n.dataset.gasNode),'#gas-current-title');
 for(const [selector,delta]of [['[data-gas-previous]',-1],['[data-gas-next]',1]])on(selector,()=>{const stops=source.nodes.filter(n=>screen!=='card'||a.work.seen.includes(n.id)),next=stops[stops.findIndex(n=>n.id===a.work.at)+delta];return next?station(next.id):false;},()=>{const stops=source.nodes.filter(n=>screen!=='card'||a.work.seen.includes(n.id)),i=stops.findIndex(n=>n.id===a.work.at);return i===0?'[data-gas-next]':i===stops.length-1?'[data-gas-previous]':'#gas-current-title';});
 root.querySelector('[data-gas-leg]')?.addEventListener('change',e=>{const n=e.currentTarget;if(!live(n)||!a||!source.legs.some(l=>l.id===n.value))return;stop();a.leg=n.value;redraw('#gas-current-title');});
 on('[data-gas-method]',n=>change('label',{legId:a.leg,methodId:n.dataset.gasMethod}),n=>attr('method',n.dataset.gasMethod));
 on('[data-gas-remove]',()=>change('remove',a.leg),'[data-gas-leg]');on('[data-gas-reference]',()=>change('reference'),'#gas-current-title');
 on('[data-gas-example]',()=>change('example'),()=>a.work.exampleSeen>=source.teaching.length?'[data-gas-fold="help"] summary':'[data-gas-example]');
 root.querySelectorAll('[data-gas-fold]').forEach(n=>n.addEventListener('toggle',()=>{if(!live(n)||!a)return;stop();a.folds[n.dataset.gasFold]=n.open;}));
 on('[data-gas-copy]',()=>{if(!raw)return false;let id=v.copies.get(card);if(!id||!v.drafts.has(id)){id=`copy:${card}`;const copy=makeSlot(raw.source,raw.work);copy.turn=a.turn;copy.leg=a.leg;copy.folds={...a.folds};v.drafts.set(id,copy);v.copies.set(card,id);}v.active=id;v.screen='draft';});
 on('[data-gas-keep]',()=>{if(!editable())return false;const id=keepGasGuide(book,source,a.work,{canExport:ctx.canExport});if(!id){status('This guide has not been kept. The notebook may be too large or this saved format unavailable. Your draft is still here. Download Grown-up notes to preserve earlier records.');return false;}let saved;try{saved=ctx.save();}catch{saved={ok:false};}const record=gasGuidesView(book).items.find(x=>x.id===id&&x.readable),kept=makeSlot(record?.raw.source||source,record?.raw.work||a.work);kept.turn=a.turn;kept.leg=a.leg;kept.folds={...a.folds};kept.status=saved?.enabled===false?'Kept in this open page. Saving is off; download Grown-up notes before closing.':saved?.ok===false?'Kept in this open page. Device storage did not save; download Grown-up notes before closing.':'This guide is kept.';if(record)Object.assign(kept,{raw:record.raw,rawSource:record.raw.source,rawWork:record.raw.work});v.readonly.set(id,kept);v.drafts.delete(active);for(const [key,value]of v.copies)if(value===active)v.copies.delete(key);v.card=id;v.screen='card';v.page=null;},'#gas-status');
 const hear=root.querySelector('[data-gas-hear]');hear?.addEventListener('click',()=>{if(!live(hear))return;stop();const visible=n=>{if(n.nodeType===3)return n.textContent+' ';if(n.nodeType!==1||n.matches('svg,button,select,[hidden],.gas-stations,.gas-actions,.gas-visit-note,[data-gas-choice]'))return '';if(n.tagName==='DETAILS'&&!n.open)return '';return [...n.childNodes].map(visible).join(' ');};hear.dataset.speak=visible(root).replace(/\s+/g,' ').trim();},{capture:true});
}
export function gasDiffusionInvitation(book,{open=false}={}){const last=lastGasGuide(book);if(!last)return '';const {raw,index}=last,s=raw.source,w=raw.work;return `<details class="gas-return" data-gas-diffusion-return${open?' open':''}><summary>Guide ${index+1} · ${esc(s.title)}</summary>${diagram(s,w)}<p class="gas-loop">${esc(s.loopNote)}</p><h3>${esc(node(s,w.at).label)}</h3><p>${esc(node(s,w.at).description)}</p>${legend(s,w)}<p>${esc(s.notice)}</p><p>${esc(s.returnQuestion)}</p><a href="#living/bodies">Open Body clues, then Cell Studio → Air and blood → Kept guides</a></details>`;}
